#!/usr/bin/env bash
# DREAM v06 · stage 1 assets (Seedream 5.0 Pro 2K). Handles = file names in film02/assets/.
set -euo pipefail
cd "$(dirname "$0")/../.."
J="python3 tools/jm.py film02/jimeng-state.json"

$J img char_pilot4 --title "@char_pilot4 · 主演 透明面罩" --ref char_pilot3 --ref ref_logo --prompt "Create a photorealistic three-panel character sheet, 16:9, three equal panels side by side with thin divider lines. The same man in every panel, identical to the man in the first reference: an American man in his mid-30s, short dark-brown hair, light natural stubble, grey-green eyes, real skin with visible pores, natural tonal variation and slight asymmetry. No airbrushing or beauty retouching. He wears exactly the matte black one-piece flight suit of the first reference with the CoolFly wordmark printed small on the left chest and large across the upper back, copied exactly from the second reference: slanted stencil letters, 'Cool' in off-white and 'Fly' in orange, never misspelled or mirrored. Black leather gloves, black boots. On his head a matte black full-face flight helmet with a perfectly clear, untinted, glass-like visor lowered; his whole face, eyes and expression are clearly visible through the visor, with only a faint natural reflection on its surface. LEFT: frontal head-and-shoulders portrait wearing the helmet, visor down, calm eyes to the lens, chest wordmark visible. CENTRE: front full-body view, standing upright, helmet on with visor down, both gloved hands visible. RIGHT: back full-body view at the same scale, the large back wordmark clearly readable. Both body panels share one ground line with the boots fully visible. Seamless neutral mid-grey studio background, broad soft even light, neutral white balance, gentle grounded shadows. No other text, logos or labels, no film filter, no illustration or CGI look."

$J img char_family --title "@char_family · 妻子和女儿" --prompt "Create a photorealistic three-panel character sheet, 16:9, three equal panels side by side with thin divider lines. The same two people in every panel: an American woman in her mid-30s with shoulder-length light-brown hair, natural makeup, warm hazel eyes, real skin with visible texture, wearing a cream knit sweater, dark jeans and white sneakers; and her 8-year-old daughter with long sandy-blonde hair, freckles, blue eyes, a gap-toothed natural smile, wearing a light denim jacket over a white T-shirt, plain navy leggings (both legs the same navy colour) and white sneakers. No airbrushing or beauty retouching, real everyday people. LEFT: head-and-shoulders portrait of both side by side, mother's hand on the girl's shoulder, both looking to the lens, relaxed warm expressions. CENTRE: front full-body view of both standing side by side. RIGHT: back full-body view of both at the same scale. Both body panels share one ground line with the shoes fully visible. Seamless neutral mid-grey studio background, broad soft even light, neutral white balance. No text, logos or labels, no film filter, no illustration or CGI look."

$J img loc_garage --title "@loc_garage · 崖边住宅车库 黎明前" --prompt "Create a photorealistic cinematic location still, 16:9: the inside of a private modern garage pavilion of a clifftop house on the California coast, just before dawn. Board-formed concrete floor, warm timber ceiling with exposed beams, a long walnut workbench along the left wall with a few neat tools and a single warm brass wall lamp switched on. The far wall is one tall full-width glass sectional garage door, closed, looking out over a cliff edge to the Pacific Ocean under deep blue pre-dawn light with low sea fog drifting. The wide centre bay of the floor is completely empty, with generous clear space and headroom for a small single-seat aircraft to stand and lift off. Seen from floor height at the back right corner, looking diagonally toward the glass door. Quiet, architectural, aspirational, like a luxury design magazine. Clean modern digital cinema look, cool blue ambient light mixed with the one warm lamp, deep clean blacks, crisp detail. No people, vehicles, aircraft or readable text."

$J img loc_coast_us --title "@loc_coast_us · 加州海岸 拱桥" --prompt "Create a photorealistic cinematic location still, 16:9: the Big Sur coast of California in the early morning, seen from the air at about 30 metres above the sea, looking along the coast. Steep golden-grass hillsides and dark rock cliffs drop into a deep blue Pacific with white surf. In the middle distance a classic open-spandrel concrete arch bridge carries a two-lane coastal highway across a deep canyon where it meets the sea. A soft bank of white sea fog lies offshore on the right and drifts into the far headlands. Low warm morning sun from the left, long shadows on the hills. Open air above the water in the foreground for an aircraft to fly through. Clean modern digital cinema look, natural saturated colour, deep clean blacks, crisp detail. No aircraft, vehicles, boats, people or readable text."

$J img loc_clouds --title "@loc_clouds · 云海日出" --prompt "Create a photorealistic cinematic location still, 16:9: high above an endless sea of soft white clouds at the exact moment of sunrise, seen from inside the sky at cloud-top height. The sun is just breaking over the far edge of the cloud sea at the centre of frame, sending long golden light across the rolling cloud tops; the sky shades from warm gold at the horizon to clear deep blue above. A few tops of coastal mountain ridges break through the clouds in the far distance on the left. Vast, silent, awe-inspiring scale. Open air in the foreground for an aircraft to fly through. Clean modern digital cinema look, rich warm colour, crisp detail, no haze wash-out. No aircraft, birds, people or readable text."

$J img loc_breakfast --title "@loc_breakfast · 崖顶早餐" --prompt "Create a photorealistic cinematic location still, 16:9: a wild grassy clifftop meadow on the California coast on a clear sunny morning, high above a layer of white sea fog that fills the ocean below the cliff edge. On the left, a small wooden table set for breakfast with a white linen tablecloth, a steel coffee pot, three ceramic mugs, a basket of pastries and two folding wooden chairs. To the right of the table, a wide flat open stretch of short grass is completely empty, with clear sky above it for a small aircraft to land. Seen from low in the grass at a wide angle. Warm golden morning light from the right, long soft shadows, wild flowers in the foreground. Clean modern digital cinema look, natural rich colour, deep clean blacks, crisp detail. No people, vehicles, aircraft or readable text."

